config.script:
# 1.25.0: the Safety Diagnostics popup - on the area that needs attention most (a fault, then needs reset or
# stopped, then isolated), else SDB. The popup's tabs reach every area.
area = 'SDB'
try:
	rank = {'flt': 4, 'rst': 3, 'stp': 3, 'act': 2}
	best, top = 'SDB', 0
	for t in booth.safety.model('SDB').get('tabs', []):
		r = rank.get(t.get('tone'), 0)
		if r > top:
			best, top = t.get('code', 'SDB'), r
	area = best
except:
	pass
booth.safety.openDiag(area)

